    ).toBe(false);
    expect(
      shouldRunForOrg({ ...org, archivedAt: toIsoTimestamp(NOW) }, NOW),
    ).toBe(false);
  });
});
/**
 * Soft-delete filtering.
 *
 * Archived rows stay in the table and disappear from every default read. The
 * cases below pin both halves of that: an archived issue is invisible unless
 * `includeArchived` is set, and archiving a project cascades to its issues.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("./_support/doubles/misc")).loggerModule);

import { AlreadyArchivedError } from "@/lib/soft-delete";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import { createTenant, issueInput, useTemporaryDatabase } from "./_support/fixtures";
import type { Tenant } from "./_support/fixtures";
import type { Issue } from "@/types/issue";

let cleanup: () => void;
let tenant: Tenant;
let live: Issue;
let archived: Issue;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("softdelete");

  live = await issueService.createIssue(
    tenant.actors.member,
    issueInput(tenant.org.id, tenant.project.id, { title: "Still open" }),
  );

  const doomed = await issueService.createIssue(
    tenant.actors.member,
    issueInput(tenant.org.id, tenant.project.id, { title: "Archived away" }),
  );

  archived = await issueService.archiveIssue(
    tenant.actors.member,
    tenant.org.id,
    doomed.id,
  );
});

afterAll(() => {
  cleanup();
});

describe("archived issues", () => {
  it("marks the row rather than deleting it", async () => {
    expect(archived.archivedAt).not.toBeNull();

    const stillThere = await issueRepo.findIssueById(
      tenant.org.id,
      archived.id,
    );
    expect(stillThere?.id).toBe(archived.id);
  });

  it("is excluded from the default listing", async () => {
    const page = await issueRepo.listIssues({
      orgId: tenant.org.id,
      limit: 25,
      cursor: null,
    });

    expect(page.items.map((issue) => issue.id)).toEqual([live.id]);
    expect(page.total).toBe(1);
  });

  it("reappears when the caller opts in", async () => {
    const page = await issueRepo.listIssues({
      orgId: tenant.org.id,
      limit: 25,
      cursor: null,
      includeArchived: true,
    });

    expect(page.total).toBe(2);
    expect(page.items.map((issue) => issue.id).sort()).toEqual(
      [live.id, archived.id].sort(),
    );
  });

  it("is excluded from the per-project count the quota reads", async () => {
    await expect(
      issueRepo.countIssues(tenant.org.id, tenant.project.id),
    ).resolves.toBe(1);

    await expect(
      issueRepo.countIssues(tenant.org.id, tenant.project.id, {
        includeArchived: true,
      }),
    ).resolves.toBe(2);
  });

  it("is excluded from the board columns", async () => {
    const columns = await issueRepo.listBoardColumns(
      tenant.org.id,
      tenant.project.id,
    );
    const ids = columns.flatMap((column) => column.issues.map((i) => i.id));

    expect(ids).toEqual([live.id]);
  });

  it("keeps its issue number reserved", async () => {
    await expect(
      issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id),
    ).resolves.toBe(3);
  });

  it("refuses to be archived twice", async () => {
    await expect(
      issueService.archiveIssue(
        tenant.actors.member,
        tenant.org.id,
        archived.id,
      ),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
  });
});

describe("archiving a project", () => {
  it("cascades to the project's live issues", async () => {
    const scratch = await projectService.createProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      name: "Scratch",
      slug: "scratch",
      key: "SCR",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });

    await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, scratch.id, { title: "Doomed with project" }),
    );

    const result = await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: scratch.id,
      archiveIssues: true,
    });

    expect(result.archivedAt).not.toBeNull();
    await expect(
      issueRepo.countIssues(tenant.org.id, scratch.id),
    ).resolves.toBe(0);
    await expect(
      issueRepo.countIssues(tenant.org.id, scratch.id, {
        includeArchived: true,
      }),
    ).resolves.toBe(1);

    const listed = await projectRepo.listProjects({
      orgId: tenant.org.id,
      limit: 25,
      cursor: null,
    });
    expect(listed.items.map((project) => project.id)).not.toContain(scratch.id);
  });
});
/** Archive/restore patches and `applyArchiveScope`. */
import { describe, expect, it } from "vitest";
import {
  AlreadyArchivedError,
  applyArchiveScope,
  archivePatch,
  assertNotArchived,
  isArchived,
  isLive,
  restorePatch,
  shouldFilterArchived,
} from "@/lib/soft-delete";
import type { IsoTimestamp } from "@/types/common";
import { makeIssue } from "../helpers/factories";

const NOW = new Date("2026-03-15T12:00:00.000Z");
const ARCHIVED_AT = "2026-03-01T09:00:00.000Z" as IsoTimestamp;

describe("lib/soft-delete", () => {
  it("reads the live/archived state from `archivedAt`", () => {
    const live = makeIssue();
    const archived = makeIssue({ archivedAt: ARCHIVED_AT });

    expect(isLive(live)).toBe(true);
    expect(isArchived(live)).toBe(false);
    expect(isLive(archived)).toBe(false);
    expect(isArchived(archived)).toBe(true);
  });

  it("filters archived rows out by default", () => {
    const rows = [makeIssue(), makeIssue({ archivedAt: ARCHIVED_AT }), makeIssue()];
    expect(applyArchiveScope(rows)).toHaveLength(2);
    expect(applyArchiveScope(rows, {})).toHaveLength(2);
    expect(applyArchiveScope(rows, { includeArchived: false })).toHaveLength(2);
  });

  it("keeps archived rows when the scope asks for them", () => {
    const rows = [makeIssue(), makeIssue({ archivedAt: ARCHIVED_AT })];
    expect(applyArchiveScope(rows, { includeArchived: true })).toHaveLength(2);
  });

  it("tells a repository when to add the archived_at predicate", () => {
    expect(shouldFilterArchived()).toBe(true);
    expect(shouldFilterArchived({})).toBe(true);
    expect(shouldFilterArchived({ includeArchived: false })).toBe(true);
    expect(shouldFilterArchived({ includeArchived: true })).toBe(false);
  });

  it("stamps archivedAt and updatedAt with the same instant", () => {
    const patch = archivePatch(NOW);
    expect(patch.archivedAt).toBe(NOW.toISOString());
    expect(patch.updatedAt).toBe(patch.archivedAt);
  });

  it("clears archivedAt on restore while still touching updatedAt", () => {
    const patch = restorePatch(NOW);
    expect(patch.archivedAt).toBeNull();
    expect(patch.updatedAt).toBe(NOW.toISOString());
  });

  it("round-trips a row through archive and restore", () => {
    const issue = makeIssue();
    const archived = { ...issue, ...archivePatch(NOW) };
    expect(isArchived(archived)).toBe(true);

    const restored = { ...archived, ...restorePatch(NOW) };
    expect(isLive(restored)).toBe(true);
  });

  it("treats double archiving as a conflict", () => {
    expect(() => assertNotArchived("Issue", "01ISS", makeIssue())).not.toThrow();
    expect(() =>
      assertNotArchived("Issue", "01ISS", makeIssue({ archivedAt: ARCHIVED_AT })),
    ).toThrow(AlreadyArchivedError);

    try {
      assertNotArchived("Issue", "01ISS", makeIssue({ archivedAt: ARCHIVED_AT }));
    } catch (error) {
      expect((error as AlreadyArchivedError).code).toBe("conflict");
      expect((error as AlreadyArchivedError).entity).toBe("Issue");
    }
  });
});

