/**
 * Permanently removes rows archived longer ago than the plan's `retentionDays`.
 *
 * Must call (do not reimplement): getPlanLimits, retentionCutoff
 */
import { getPlanLimits } from "@/config/plan-limits";
import { createLogger } from "@/lib/logger";
import { retentionCutoff } from "@/lib/soft-delete";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { IssueId, OrgId } from "@/types/common";

const ORG_BATCH = 25;
const PAGE_SIZE = 100;

const logger = createLogger("cleanup-archived-job");

/**
 * The retention sweep. Archived issues are a trash: they stay restorable for
 * as long as the plan promises and no longer. The cut-off comes from
 * `retentionDays`, so an enterprise tenant keeps years of history where a free
 * one keeps a month — and `restoreIssue` refuses exactly the issues this sweep
 * deletes, because both read the same cut-off.
 *
 * Every expired issue of every workspace is purged for good, together with
 * its label links, comments, attachments and their search documents, and the
 * attachments' storage goes back to the counter. The audit rows past the
 * window are purged outright as well.
 */
export async function runCleanupArchivedJob(now: Date): Promise<JobResult> {
  return runJob("cleanup-archived", async (result) => {
    let afterOrgId: OrgId | null = null;

    for (;;) {
      const orgIds = await orgRepo.listOrgIds(ORG_BATCH, afterOrgId);
      if (orgIds.length === 0) break;

      for (const orgId of orgIds) {
        try {
          await sweepOrg(orgId, now, result);
        } catch (error) {
          result.failed += 1;
          logger.error("retention sweep failed", {
            orgId,
            reason: error instanceof Error ? error.message : String(error),
          });
        }
      }

      afterOrgId = orgIds[orgIds.length - 1] ?? null;
    }
  });
}

async function sweepOrg(
  orgId: OrgId,
  now: Date,
  result: JobResult,
): Promise<void> {
  const org = await orgRepo.findOrgById(orgId);
  if (!org) return;

  const { retentionDays } = getPlanLimits(org.plan);
  const cutoff = retentionCutoff(now, retentionDays);

  let afterIssueId: IssueId | null = null;

  for (;;) {
    const expired = await issueRepo.listExpiredIssues(
      orgId,
      cutoff,
      PAGE_SIZE,
      afterIssueId,
    );
    if (expired.length === 0) break;

    for (const issue of expired) {
      try {
        const purged = await issueRepo.purgeIssue(orgId, issue.id);
        if (purged === null) continue;

        // Archived issues are not counted in `issuesUsed`, so only the
        // attachments' storage goes back to the counter.
        if (purged.freedMb > 0) {
          await usageRepo.incrementUsage(orgId, {
            storageMbUsed: -purged.freedMb,
          });
        }
        result.processed += 1;
      } catch (error) {
        result.failed += 1;
        logger.error("issue purge failed", {
          orgId,
          issueId: issue.id,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }

    afterIssueId = expired[expired.length - 1]?.id ?? null;
  }

  try {
    const purged = await activityRepo.purgeActivityBefore(orgId, cutoff);
    result.processed += purged;
  } catch (error) {
    result.failed += 1;
    logger.error("activity purge failed", {
      orgId,
      reason: error instanceof Error ? error.message : String(error),
    });
  }
}

