/**
 * Domain events published by the service layer.
 *
 * Services stay decoupled from notifications, search, the audit log and
 * webhooks by announcing facts on the bus. If an event stops firing — or fires
 * with the wrong payload — every one of those concerns silently stops working,
 * which is why the contract is pinned here rather than through its consumers.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("./_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import { createTenant, issueInput, useTemporaryDatabase } from "./_support/fixtures";
import type { Tenant } from "./_support/fixtures";
import type { TaskflowEventMap, TaskflowEventType, Unsubscribe } from "@/types/event";

let cleanup: () => void;
let tenant: Tenant;
const detachers: Unsubscribe[] = [];

/** Collects every payload delivered for one event type during a test. */
function capture<K extends TaskflowEventType>(type: K): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  detachers.push(
    subscribe(type, (payload) => {
      seen.push(payload);
    }),
  );
  return seen;
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("events");
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
});

afterAll(() => {
  cleanup();
});

describe("issue.created", () => {
  it("is emitted once per created issue, carrying the actor and the issue", async () => {
    const seen = capture("issue.created");

    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Emit me",
        assigneeId: tenant.userIds.admin,
      }),
    );

    expect(seen).toHaveLength(1);
    expect(seen[0]).toMatchObject({
      orgId: tenant.org.id,
      actorId: tenant.userIds.member,
      issueId: issue.id,
      projectId: tenant.project.id,
      title: "Emit me",
      assigneeId: tenant.userIds.admin,
      priority: "none",
    });
/**
 * Test doubles for the `src/lib` helpers owned by E.
 *
 * The server layer legitimately depends on them, but they are still stubs at
 * the time this suite runs, so each is replaced with the smallest faithful
 * implementation the assertions need. Swap-in only — no server code is mocked.
 */
import type { UserId } from "@/types/common";
import type { MemberWithUser } from "@/types/member";
import type { IsoTimestamp, OrgId } from "@/types/common";

/* -------------------------------------------------------------- @/lib/hash */

export const hashModule = {
  hashPassword: async (password: string): Promise<string> =>
    `scrypt$${password.length}$${simpleHash(password)}`,
  verifyPassword: async (password: string, hash: string): Promise<boolean> =>
    (await hashModule.hashPassword(password)) === hash,
  hashToken: (token: string): string => `sha256$${simpleHash(token)}`,
  randomToken: (bytes = 32): string =>
    `t${simpleHash(String(tokenCounter++))}`.padEnd(bytes, "x"),
};

let tokenCounter = 1;

/* -------------------------------------------------------- @/lib/rate-limit */

/** Verdicts the suite can steer: the default is "always allowed". */
export const rateLimitState = { allowed: true, remaining: 100 };

/**
 * Index maintenance on issue and comment writes.
 *
 * Owner C implements `@/server/services/search-service`.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as searchService from "@/server/services/search-service";
import { rateLimitState } from "../server/_support/doubles/misc";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { Unsubscribe } from "@/types/event";

let cleanup: () => void;
let tenant: Tenant;
let detach: Unsubscribe;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detach = searchService.registerSearchListeners();
  tenant = await createTenant("searchsvc", "growth");
});

afterAll(() => {
  detach();
  cleanup();
});

afterEach(() => {
  rateLimitState.allowed = true;
  rateLimitState.remaining = 100;
});

describe("services/search-service", () => {
  it("indexes an issue and a comment on creation", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Zulu index target" }),
    );
    const comment = await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "Yankee index target",
      parentId: null,
      mentionedUserIds: [],
    });

    const issueHits = await searchService.search(tenant.actors.member, {
      orgId: tenant.org.id,
      q: "Zulu",
      kinds: ["issue"],
      limit: 25,
      cursor: null,
    });
import { z } from "zod";
import { attachmentIdSchema, issueIdSchema, orgIdSchema } from "./common";

/** 25 MiB, also enforced against the plan's `storageMb` quota. */
export const MAX_ATTACHMENT_BYTES = 25 * 1024 * 1024;

export const createAttachmentSchema = z.object({
  orgId: orgIdSchema,
  issueId: issueIdSchema,
  filename: z.string().min(1).max(255),
  contentType: z.string().min(3).max(128),
  sizeBytes: z.number().int().min(1).max(MAX_ATTACHMENT_BYTES),
});

export const deleteAttachmentSchema = z.object({
  orgId: orgIdSchema,
  attachmentId: attachmentIdSchema,
});

export type CreateAttachmentInput = z.infer<typeof createAttachmentSchema>;
export type DeleteAttachmentInput = z.infer<typeof deleteAttachmentSchema>;

