    detachers.push(subscribe("issue.restored", (payload) => void seen.push(payload)));

    const attempt = issueService.restoreIssue(tenant.actors.member, tenant.org.id, live.id);

    await expect(attempt).rejects.toBeInstanceOf(RestoreRefusedError);
    await expect(attempt).rejects.toMatchObject({ code: "conflict", reason: "not_archived" });
    expect(seen).toHaveLength(0);
  });

  it("lets an issue be restored until the retention window has fully elapsed", async () => {
    const now = new Date("2026-09-01T12:00:00.000Z");
    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(now);

    const justInside = await create(tenant, "One millisecond left");
    const justOutside = await create(tenant, "Exactly expired");
    await archive(tenant, justInside);
    await archive(tenant, justOutside);
    archivedDaysAgo(justInside, 90, new Date(now.getTime() + 1));
    archivedDaysAgo(justOutside, 90, now);

    await expect(
      issueService.restoreIssue(tenant.actors.member, tenant.org.id, justOutside.id),
    ).rejects.toMatchObject({ reason: "expired" });

    await expect(
      issueService.restoreIssue(tenant.actors.member, tenant.org.id, justInside.id),
    ).resolves.toMatchObject({ archivedAt: null });

    // Expired stays expired even though the sweep has not removed the row yet.
    expect(await issueRepo.findIssueById(tenant.org.id, justOutside.id)).not.toBeNull();
  });

  it("refuses an issue whose project is archived", async () => {
    const project = await projectService.createProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      name: "Doomed",
      slug: "doomed",
      key: "DOOM",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });
    const issue = await create(tenant, "Inside a doomed project", project.id);
    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: project.id,
      archiveIssues: true,
    });

    await expect(
      issueService.restoreIssue(tenant.actors.member, tenant.org.id, issue.id),
    ).rejects.toMatchObject({ reason: "project_archived" });
  });

  it("refuses when the project has no room under the plan's issue quota", async () => {
    const free = await createTenant("trashfree", "free"); // 100 issues per project
    const first = await create(free, "Number one");
    await archive(free, first);
    for (let n = 0; n < 100; n += 1) await create(free, `Filler ${n}`);

    const seen: unknown[] = [];
    detachers.push(subscribe("issue.restored", (payload) => void seen.push(payload)));

    await expect(
      issueService.restoreIssue(free.actors.member, free.org.id, first.id),
    ).rejects.toMatchObject({ code: "conflict", reason: "quota" });
    expect(seen).toHaveLength(0);
    expect((await issueRepo.findIssueById(free.org.id, first.id))?.archivedAt).not.toBeNull();
  });

  it("maps a refusal to the conflict code", () => {
    const shape = toAppError(new RestoreRefusedError("expired"));
    expect(shape.code).toBe("conflict");
    expect(shape.meta).toMatchObject({ reason: "expired" });
  });
});

describe("the retention sweep", () => {
  const NOW = new Date("2026-09-01T12:00:00.000Z");

  it("purges an expired issue together with everything that hangs off it", async () => {
    const t = await createTenant("purgeall", "starter");
    const label = await labelRepo.insertLabel({
      orgId: t.org.id,
      name: "purge-me",
      color: "#ef4444",
      description: null,
    });
    const doomed = await issueService.createIssue(t.actors.member, {
      ...issueInput(t.org.id, t.project.id, { title: "Doomed Axolotl" }),
      labelIds: [label.id],
    });
    const kept = await create(t, "Kept Axolotl");

    const comment = await commentService.createComment(t.actors.member, {
      orgId: t.org.id,
      issueId: doomed.id,
      body: "Doomed comment",
      parentId: null,
      mentionedUserIds: [],
    });
    const deletedComment = await commentService.createComment(t.actors.member, {
      orgId: t.org.id,
      issueId: doomed.id,
      body: "Doomed and already deleted comment",
      parentId: null,
      mentionedUserIds: [],
    });
    await commentService.deleteComment(t.actors.admin, t.org.id, deletedComment.id);
    const keptComment = await commentService.createComment(t.actors.member, {
      orgId: t.org.id,
      issueId: kept.id,
      body: "Kept comment",
      parentId: null,
      mentionedUserIds: [],
    });
    await searchRepo.upsertSearchDocument(t.org.id, "issue", doomed.id, "Doomed Axolotl", t.project.id);
    await searchRepo.upsertSearchDocument(t.org.id, "issue", kept.id, "Kept Axolotl", t.project.id);

    await attachmentService.addAttachment(t.actors.member, {
      orgId: t.org.id,
      issueId: doomed.id,
      filename: "big.bin",
      contentType: "application/octet-stream",
      sizeBytes: 3 * MB + 1, // counted as 4 MB
    });
    await attachmentService.addAttachment(t.actors.member, {
      orgId: t.org.id,
      issueId: doomed.id,
      filename: "small.bin",
      contentType: "application/octet-stream",
      sizeBytes: 10, // counted as 1 MB
    });
    await attachmentService.addAttachment(t.actors.member, {
      orgId: t.org.id,
      issueId: kept.id,
      filename: "kept.bin",
      contentType: "application/octet-stream",
      sizeBytes: 2 * MB, // counted as 2 MB
    });

    await archive(t, doomed);
    archivedDaysAgo(doomed, 90, NOW);
    const before = await usageRepo.getUsage(t.org.id);
    expect(before.storageMbUsed).toBe(7);

    const result = await runCleanupArchivedJob(NOW);
    expect(result.failed).toBe(0);

    expect(await issueRepo.findIssueById(t.org.id, doomed.id)).toBeNull();
    expect(await issueRepo.findIssueById(t.org.id, kept.id)).not.toBeNull();

    const db = getDb();
    expect(db.select().from(issueLabels).where(eq(issueLabels.issueId, doomed.id)).all()).toEqual([]);
    expect(db.select().from(comments).where(eq(comments.issueId, doomed.id)).all()).toEqual([]);
    expect(db.select().from(attachments).where(eq(attachments.issueId, doomed.id)).all()).toEqual([]);
    expect(await attachmentRepo.listAttachments(t.org.id, kept.id)).toHaveLength(1);
    expect(db.select().from(comments).where(eq(comments.id, keptComment.id)).all()).toHaveLength(1);

    const issueDocs = await indexedIds(t.org.id, "issue");
    expect(issueDocs).not.toContain(doomed.id);
    expect(issueDocs).toContain(kept.id);
    const commentDocs = await indexedIds(t.org.id, "comment");
    expect(commentDocs).not.toContain(comment.id);
    expect(commentDocs).not.toContain(deletedComment.id);
    expect(commentDocs).toContain(keptComment.id);

    const after = await usageRepo.getUsage(t.org.id);
    expect(after.storageMbUsed).toBe(2);
    expect(after.issuesUsed).toBe(before.issuesUsed);
    const recount = await usageRepo.recomputeUsage(t.org.id);
    expect(recount.storageMbUsed).toBe(after.storageMbUsed);
  });

  it("leaves an issue alone until the whole retention window has passed", async () => {
    const t = await createTenant("purgewindow", "starter");
    const inside = await create(t, "Inside the window");
    const edge = await create(t, "On the edge");
    const live = await create(t, "Never archived");
    await archive(t, inside);
    await archive(t, edge);
    archivedDaysAgo(inside, 90, new Date(NOW.getTime() + 1));
    archivedDaysAgo(edge, 90, NOW);

    await runCleanupArchivedJob(NOW);

    expect(await issueRepo.findIssueById(t.org.id, inside.id)).not.toBeNull();
    expect(await issueRepo.findIssueById(t.org.id, live.id)).not.toBeNull();
    expect(await issueRepo.findIssueById(t.org.id, edge.id)).toBeNull();
  });

  it("uses each workspace's own retention", async () => {
    const free = await createTenant("purgefree", "free"); // 30 days
    const growth = await createTenant("purgegrowth", "growth"); // 365 days
    const a = await create(free, "Free, 40 days old");
    const b = await create(growth, "Growth, 40 days old");
    await archive(free, a);
    await archive(growth, b);
    archivedDaysAgo(a, 40, NOW);
    archivedDaysAgo(b, 40, NOW);

    await runCleanupArchivedJob(NOW);

    expect(await issueRepo.findIssueById(free.org.id, a.id)).toBeNull();
    expect(await issueRepo.findIssueById(growth.org.id, b.id)).not.toBeNull();
  });

  it("purges every expired issue of the workspace, across projects and past one page", async () => {
    const t = await createTenant("purgemany", "growth");
    const second = await projectService.createProject(t.actors.admin, {
      orgId: t.org.id,
      name: "Second",
      slug: "second",
      key: "SEC",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });

    const doomed: Issue[] = [];
    for (let n = 0; n < 130; n += 1) {
      doomed.push(await create(t, `Doomed ${n}`, n % 2 === 0 ? t.project.id : second.id));
    }
    const survivor = await create(t, "Survivor", second.id);
    for (const issue of doomed) {
      await archive(t, issue);
      archivedDaysAgo(issue, 400, NOW);
    }

    await runCleanupArchivedJob(NOW);

    const remaining = await issueRepo.listIssues({
      orgId: t.org.id,
      limit: 100,
      cursor: null,
      includeArchived: true,
    });
    expect(remaining.items.map((issue) => issue.id)).toEqual([survivor.id]);
  });

  it("never reuses an issue number, even one held by a purged issue", async () => {
    const t = await createTenant("purgenumbers", "starter");
    const one = await create(t, "One");
    const two = await create(t, "Two");
    const three = await create(t, "Three");
    expect([one.number, two.number, three.number]).toEqual([1, 2, 3]);

    await archive(t, three);
    archivedDaysAgo(three, 100, NOW);
    await archive(t, two);
    archivedDaysAgo(two, 100, NOW);

    await runCleanupArchivedJob(NOW);

    const next = await create(t, "Four");
    expect(next.number).toBe(4);
    const after = await create(t, "Five");
    expect(after.number).toBe(5);
  });

  it("makes a purged issue unrestorable", async () => {
    const t = await createTenant("purgerestore", "starter");
    const issue = await create(t, "Gone for good");
    await archive(t, issue);
    archivedDaysAgo(issue, 200, NOW);

    await runCleanupArchivedJob(NOW);

    await expect(
      issueService.restoreIssue(t.actors.member, t.org.id, issue.id),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("still purges the audit rows past the window", async () => {
    const t = await createTenant("purgeaudit", "starter");
    const issue = await create(t, "Audited");
    const old = new Date(NOW.getTime() - 200 * DAY_MS);
    await activityRepo.insertActivity({
      orgId: t.org.id,
      action: "issue.created",
      actorId: t.userIds.member,
      subjectKind: "issue",
      subjectId: issue.id,
      projectId: t.project.id,
      summary: "ancient",
      metadata: {},
      occurredAt: toIsoTimestamp(old),
    });

    await runCleanupArchivedJob(NOW);

    const trail = await activityRepo.listActivityForSubject(t.org.id, "issue", issue.id);
    expect(trail.map((event) => event.summary)).not.toContain("ancient");
  });
});

